# -*- coding: utf-8 -*-
# @tvbox-role manager
"""
源管家 —— 本地 PY/JS 源自动加载管理器 (PeekPro / TVBox 系壳)
=============================================================

用法 (三步):
1. 首次进入本站点时, 自动在手机存储根目录创建「源管家」文件夹:
     存储根/源管家/py   <- 把 .py 爬虫放进这里
     存储根/源管家/js   <- 把 .js 爬虫放进这里
   (只扫描这两个目录, 含子目录; 放在别处的文件不会被收录)
2. 回到本站点, 点「⚡ 一键扫描并加载」。
3. 重启 App (或刷新配置), 扫到的源自动出现在站点列表。

工作原理 (按 PeekPro 1.5.8 反编译结论实现):
- PeekPro 的 PY 爬虫跑在 App 进程内的 Python (Chaquopy) 里, 配置由 Dart 层
  通过 proxy_handler.set_config(configJson, configDir) 注入; load_spider 仅
  接受 ./ (相对 configDir) / http 下载 / os.path.exists 通过的本地路径。
- 本脚本在扫描时读取该实时配置, 自动定位本站点的 siteKey; 把扫到的源按
  配置中已有源的格式镜像合并写入站点列表文件 (configDir / App 数据目录 /
  /sdcard/peekpro 下形如 sources/config 的 json), api/ext 注入为本地绝对
  路径, 幂等可重复执行, 写入前自动备份 .bak, 已删除的源同步清理。
- 若当前配置是远程 URL (无本地文件), 无法注入时会明确提示。

图片说明:
- 卡片图标内嵌在脚本中 (首次运行释放到 源管家/assets/)。
- 在 PeekPro 内通过本地代理显示: http://127.0.0.1:{port}/proxy?do=py
  &siteKey={本站点key}&pic={图标名}, 由本脚本的 localProxy 返回图片字节。
- 其他壳回退为绝对路径 file:/// URI。

兼容说明:
- 同时保留 TV/CustomCsp/registry.json 注入 (部分 TVBox 系壳读取该注册表)。
- 手工添加过同一文件的源不会重复生成; 文件删除后对应站点自动移除。

文件标识 (放在爬虫文件头部注释中):
- @tvbox-source : 强制收录。 @tvbox-ignore : 忽略。
- @tvbox-role manager/library/extension : 不作为站点收录。

可选: init 的 extend 参数支持 JSON 覆盖注册表路径:
{"registry": "TV/CustomCsp/registry.json"}
"""

import base64
import hashlib
import json
import os
import re
import struct
import threading
import urllib.parse
import zlib

try:
    from base.spider import Spider as _BaseSpider
except Exception:
    _BaseSpider = object


def _detect_storage_root():
    candidates = []
    external = str(os.environ.get("EXTERNAL_STORAGE", "")).strip()
    if external:
        candidates.append(external)
    candidates.extend(("/sdcard", "/storage/emulated/0", os.path.expanduser("~/storage/shared")))
    seen = set()
    for candidate in candidates:
        path = os.path.abspath(os.path.expanduser(candidate))
        real = os.path.realpath(path)
        if real in seen:
            continue
        seen.add(real)
        if os.path.isdir(path):
            return real
    return os.path.abspath(external or "/sdcard")


def _detect_base_dir(storage_root):
    """定位站点根目录: 优先 TVBOX_HOME, 其次 tvbox/TVBox (大小写不敏感)"""
    configured = str(os.environ.get("TVBOX_HOME", "")).strip()
    candidates = [configured] if configured else []
    candidates.extend((os.path.join(storage_root, "tvbox"), os.path.join(storage_root, "TVBox")))
    for candidate in candidates:
        path = os.path.realpath(os.path.abspath(os.path.expanduser(candidate)))
        if os.path.isdir(path):
            return path
    try:
        for name in os.listdir(storage_root):
            if name.lower() == "tvbox" and os.path.isdir(os.path.join(storage_root, name)):
                return os.path.realpath(os.path.join(storage_root, name))
    except Exception:
        pass
    return os.path.realpath(os.path.join(storage_root, "tvbox"))


STORAGE_ROOT = _detect_storage_root()
LOCAL_BASE_DIR = _detect_base_dir(STORAGE_ROOT)

# 固定工作目录: 存储根/源管家/{py,js,assets}
BASE_DIR = os.path.join(STORAGE_ROOT, "源管家")
PY_DIR = os.path.join(BASE_DIR, "py")
JS_DIR = os.path.join(BASE_DIR, "js")
ASSETS_DIR = os.path.join(BASE_DIR, "assets")

# 卡片图标 (240x240 JPEG, base64 内嵌, 首次运行释放到 ASSETS_DIR)
ICONS_B64 = {
    "status": "",
    "folder": "",
    "scan": "",
    "clear": "",
    "py": "",
    "js": "",
}


class Spider(_BaseSpider):

    # ==================== 可调配置 ====================
    # CustomCsp 注册表 (部分 TVBox 系壳读取), 相对存储根, 用第一个已存在的
    REGISTRY_CANDIDATES = (
        "TV/CustomCsp/registry.json",
        "TVBox/CustomCsp/registry.json",
    )
    GENERATED_PREFIX = "local_auto_"
    JS_API = "./lib/drpy2-fast.min.js"
    MAX_SCAN_FILES = 3000
    MAX_SCAN_DEPTH = 6
    MAX_SOURCE_SIZE = 5 * 1024 * 1024
    HEAD_READ_LIMIT = 64 * 1024
    PAGE_SIZE = 30
    # 站点列表 json 里可能的数组字段名
    SITE_LIST_KEYS = ("sites", "sources", "list", "items", "data")
    # 自动注入时额外搜索的目录 (PeekPro 外部数据目录)
    SYNC_SEARCH_ROOTS = ("/storage/emulated/0/peekpro",)
    SYNC_MAX_FILES = 60
    SYNC_MAX_DEPTH = 2
    # 扫描排除 (小写匹配)
    SKIP_DIRS = {"lib", "libs", "__pycache__", ".git", "node_modules", "base", "assets"}
    JS_SKIP_NAMES = {"drpy2-fast.min.js", "drpy2.min.js", "drpy2.js"}
    JS_SKIP_SUFFIXES = (".ext.js", ".extension.js", ".user.js")

    STATUS_ID = "__auto_loader_status__"
    STATE_ID = "__auto_loader_state__"
    RESCAN_ID = "__auto_loader_rescan__"
    CLEAR_ID = "__auto_loader_clear__"
    HELP_ID = "__auto_loader_help__"

    def __init__(self):
        self.name = "源管家"
        self.lock = threading.RLock()
        self.registry_path = self._detect_registry_path()
        self._ensure_work_dirs()
        self.sources = []
        self.ignored = []
        self.warnings = []
        self.error = ""
        self.write_state = "尚未扫描"
        self.scan_time = ""
        self.manual_sites = 0
        self.generated_sites = 0
        self.manual_skipped = []
        self.manual_sources = []
        self.old_auto = {}
        self.removed = []
        self.sync_notes = []
        self.site_key = ""   # 本站点在 App 当前配置中的 key (PeekPro 运行时发现)
        self.proxy_port = 0  # App 本地代理端口 (PeekPro 运行时发现)

    # ==================== 工作目录与图标 ====================

    def _ensure_work_dirs(self):
        """创建 源管家/py、js、assets, 并把内嵌图标释放到 assets"""
        for path in (PY_DIR, JS_DIR, ASSETS_DIR):
            try:
                if not os.path.isdir(path):
                    os.makedirs(path)
            except Exception:
                pass
        for name, data in ICONS_B64.items():
            target = os.path.join(ASSETS_DIR, name + ".jpg")
            try:
                if os.path.isfile(target) and os.path.getsize(target) > 0:
                    continue
                with open(target, "wb") as fp:
                    fp.write(base64.b64decode(data))
            except Exception:
                pass

    # ==================== 图片: 本地代理优先, file URI 兜底 ====================

    def _pic_url(self, name):
        if not (self.proxy_port and self.site_key):
            # 扫描尚未执行或定位失败时, 主动探测一次代理端口与自身 key,
            # 避免图片退回到 file:// (PeekPro 不加载外部存储的 file:// 图片)
            self.proxy_port = self._detect_proxy_port()
            env = self._app_env()
            if env:
                self.site_key = env["our_key"]
        if self.proxy_port and self.site_key:
            return "http://127.0.0.1:{}/proxy?do=py&siteKey={}&pic={}".format(
                self.proxy_port, urllib.parse.quote(self.site_key), name)
        # 最后兜底: data URI 内嵌图片, 不依赖网络与文件权限
        data = ICONS_B64.get(name)
        if data:
            return "data:image/jpeg;base64,{}".format(data)
        return self._abs_file_url(os.path.join(ASSETS_DIR, name + ".jpg"))

    def localProxy(self, params):
        """PeekPro 本地代理入口: /proxy?do=py&siteKey={key}&pic={name}
        返回 [状态码, 类型, 字节], proxy_handler 会自动 base64 回传"""
        p = params if isinstance(params, dict) else {}
        pic = str(p.get("pic") or "").strip()
        if pic and re.fullmatch(r"[A-Za-z0-9_]{1,40}", pic):
            try:
                with open(os.path.join(ASSETS_DIR, pic + ".jpg"), "rb") as fp:
                    return [200, "image/jpeg", fp.read()]
            except Exception:
                pass
        return [404, "text/plain", "pic not found"]

    # ==================== PeekPro 进程内环境探测 ====================

    def _app_env(self):
        """读取 proxy_handler 注入的实时配置。
        返回 {"config":dict, "config_dir":str, "our_key":str, "py":dict, "js":dict}
        非 PeekPro 环境 (无 proxy_handler 模块) 返回 None"""
        try:
            import proxy_handler as ph
        except Exception:
            return None
        env = {"config": None, "config_dir": "", "our_key": "", "py": None, "js": None}
        cfg = getattr(ph, "_current_config", None)
        if isinstance(cfg, dict):
            env["config"] = cfg
        env["config_dir"] = str(getattr(ph, "_config_dir", "") or "")
        sites = self._extract_site_list(cfg)
        our_name = str(getattr(self, "name", "") or "源管家").strip()
        # 1) 优先按站点名称定位自身 (Hive 同步后 filePath 会变成内部副本名,
        #    不能再靠 api 文件名 == 源管家.py 匹配)
        for s in sites:
            if str(s.get("name") or "").strip() == our_name:
                env["our_key"] = str(s.get("key") or "")
                break
        # 2) 兜底: api 文件名 == 源管家.py (旧版本/外部配置场景)
        if not env["our_key"]:
            for s in sites:
                api = urllib.parse.unquote(str(s.get("api") or s.get("url") or ""))
                api = api.replace("file://", "")
                if os.path.basename(api.replace("\\", "/")).lower() == "源管家.py":
                    env["our_key"] = str(s.get("key") or "")
                    break
        # 3) 兜底: 按 key 前缀找本脚本生成的自体站点
        if not env["our_key"]:
            for s in sites:
                if str(s.get("key") or "").startswith(self.GENERATED_PREFIX + "py_"):
                    env["our_key"] = str(s.get("key") or "")
                    break
        # 模板条目: 排除本站点自身 (其 api 同样以 .py 结尾, 会被误选为模板)
        env["py"] = next((s for s in sites
                          if str(s.get("key") or "") != env["our_key"]
                          and str(s.get("api") or "").lower().endswith(".py")), None)
        env["js"] = next((s for s in sites
                          if str(s.get("key") or "") != env["our_key"]
                          and (str(s.get("api") or "").lower().endswith(".js")
                               or str(s.get("ext") or "").lower().endswith(".js"))), None)
        return env

    def _detect_proxy_port(self):
        """PeekPro: base.localProxy.set_port 由原生层设置"""
        try:
            from base import localProxy as lp
            return int(lp.get_port())
        except Exception:
            return 0

    def _app_context(self):
        """PeekPro 进程内 Application Context (Chaquopy Java 互操作)"""
        try:
            from com.chaquo.python import Python
            return Python.getPlatform().getApplication()
        except Exception:
            return None

    def _app_files_dir(self):
        ctx = self._app_context()
        if ctx is None:
            return ""
        try:
            return ctx.getFilesDir().getAbsolutePath()
        except Exception:
            return ""

    # ==================== App 内部存储自省 (PeekPro 站点真实存储) ====================

    def _sp_entries(self):
        """枚举 FlutterSharedPreferences 的全部条目 {key: value}。
        PeekPro 注册了 shared_preferences 插件, 自定义站点大概率存这里"""
        ctx = self._app_context()
        if ctx is None:
            return {}
        try:
            raw = ctx.getSharedPreferences("FlutterSharedPreferences", 0).getAll()
            try:
                return {str(k): raw.get(k) for k in raw.keySet()}
            except Exception:
                return dict(raw)
        except Exception:
            return {}

    def _sp_put(self, key, value_str):
        ctx = self._app_context()
        if ctx is None:
            return False
        try:
            sp = ctx.getSharedPreferences("FlutterSharedPreferences", 0)
            return bool(sp.edit().putString(key, value_str).commit())
        except Exception:
            return False

    def _sp_data_dir(self):
        ctx = self._app_context()
        if ctx is None:
            return ""
        try:
            return str(ctx.getApplicationInfo().dataDir)
        except Exception:
            return ""

    def _sp_site_stores(self):
        """返回 SharedPreferences 中值为站点列表 JSON 的条目 [(key, data, 原始字符串)]"""
        stores = []
        for k, v in self._sp_entries().items():
            if not isinstance(v, str) or len(v) < 20 or len(v) > self.MAX_SOURCE_SIZE:
                continue
            try:
                data = json.loads(v)
            except Exception:
                continue
            lst, _ = self._find_site_list(data)
            if lst is not None:
                stores.append((k, data, v))
        return stores

    def _sync_shared_prefs(self, env):
        """自省 SharedPreferences: 找到值为站点列表 JSON 的条目并合并注入。
        返回成功写回的条目数"""
        entries = self._sp_entries()
        if not entries:
            self.sync_notes.append("SharedPreferences 不可读 (非 Chaquopy 环境), 走文件注入")
            return 0
        self.sync_notes.append("SharedPreferences 共 {} 个条目, 开始自省...".format(len(entries)))
        hits = self._sp_site_stores()
        if not hits:
            self.sync_notes.append(
                "SharedPreferences 中未发现站点列表条目 (可能用 sqflite 或新版 pb 格式存储)")
            self._note_pb_pref()
            return 0
        written = 0
        for k, data, old_raw in hits:
            lst, _ = self._find_site_list(data)
            try:
                changed = self._merge_into_list(lst, env)
            except Exception as exc:
                self.sync_notes.append("SharedPreferences[{}] 合并失败: {}".format(k, exc))
                continue
            if not changed:
                self.sync_notes.append("SharedPreferences[{}] 已是最新".format(k))
                continue
            new_raw = json.dumps(data, ensure_ascii=False)
            safe = re.sub(r"[^A-Za-z0-9_.-]", "_", k)[-60:] or "sp"
            backup = os.path.join(ASSETS_DIR, "sp_bak_{}.json".format(safe))
            try:
                with open(backup, "wb") as fp:
                    fp.write(old_raw.encode("utf-8"))
            except Exception:
                backup = "(备份失败)"
            if self._sp_put(k, new_raw):
                written += 1
                self.sync_notes.append("✅ 已注入 {} 项 -> SharedPreferences[{}] (原值备份: {})".format(
                    changed, k, backup))
            else:
                self.sync_notes.append("SharedPreferences[{}] 写回失败".format(k))
        return written

    def _note_pb_pref(self):
        """检测新版 shared_preferences 的 protobuf 文件 (getAll 读不到)"""
        data_dir = self._sp_data_dir()
        if not data_dir:
            return
        pb = os.path.join(data_dir, "shared_prefs", "FlutterSharedPreferences.preferences_pb")
        if os.path.isfile(pb):
            self.sync_notes.append("⚠️ 检测到新版 pb 偏好文件 ({}字节), 若本次未生效请把状态页反馈".format(
                os.path.getsize(pb)))

    def _note_sqlite_tables(self):
        """只读自省 sqflite 数据库: 把含站点结构的表记进 notes (不写入, 避免破坏)"""
        try:
            import sqlite3
        except Exception:
            return
        roots = []
        data_dir = self._sp_data_dir()
        if data_dir:
            roots.append(os.path.join(data_dir, "databases"))
            roots.append(os.path.join(data_dir, "app_flutter"))
        files_dir = self._app_files_dir()
        if files_dir and files_dir not in roots:
            roots.append(files_dir)
        seen, checked = set(), 0
        for root in roots:
            if not root or not os.path.isdir(root) or root in seen:
                continue
            seen.add(root)
            try:
                walk = list(os.walk(root))
            except Exception:
                continue
            for dirpath, dirnames, filenames in walk:
                if os.path.relpath(dirpath, root).count(os.sep) >= 2:
                    dirnames[:] = []
                    continue
                for fn in filenames:
                    low = fn.lower()
                    if not low.endswith((".db", ".sqlite")) \
                            or low.endswith(("-wal", "-shm", "-journal")):
                        continue
                    if checked >= self.SYNC_MAX_FILES:
                        return
                    checked += 1
                    p = os.path.join(dirpath, fn)
                    try:
                        conn = sqlite3.connect(p)
                        cur = conn.cursor()
                        cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
                        tables = [str(r[0]) for r in cur.fetchall()]
                        hits = []
                        for tname in tables[:40]:
                            try:
                                cur.execute('SELECT * FROM "{}" LIMIT 5'.format(tname.replace('"', '""')))
                                rows = cur.fetchall()
                            except Exception:
                                continue
                            blob = " ".join(str(c) for row in rows for c in row
                                            if isinstance(c, (str, bytes)))[:4000]
                            if '"api"' in blob or '"sites"' in blob or '"vod_id"' in blob:
                                hits.append(tname)
                        conn.close()
                        if hits:
                            self.sync_notes.append("SQLite 发现: {} -> 表 {}".format(fn, ", ".join(hits)))
                    except Exception:
                        continue

    # ==================== 壳协议接口 ====================

    def getName(self):
        return self.name

    def init(self, extend=""):
        text = str(extend or "").strip()
        if text.startswith("{"):
            try:
                cfg = json.loads(text)
                registry = str(cfg.get("registry", "")).strip()
                if registry:
                    self.registry_path = (
                        registry
                        if os.path.isabs(registry)
                        else os.path.join(STORAGE_ROOT, registry)
                    )
            except Exception as exc:
                self.warnings.append("extend 配置解析失败: {}".format(exc))

    def getDependence(self):
        return []

    def homeContent(self, filter):
        self._ensure_scanned(force=True)  # 每次进入站点自动重新扫描
        total = len(self.sources) + len(self.manual_sources) + len(self.removed)
        classes = [{"type_id": "all", "type_name": "全部 ({})".format(total)}]
        for stype in ("PY", "JS"):
            count = len([s for s in self.sources + self.manual_sources if s["type"] == stype])
            if count:
                classes.append({"type_id": stype, "type_name": "{} ({})".format(stype, count)})
        if self.ignored:
            classes.append({"type_id": "ignored", "type_name": "忽略 ({})".format(len(self.ignored))})
        return {"class": classes, "list": self._home_items()}

    def homeVideoContent(self):
        # 必须返回空: PeekPro 会把 homeContent.list 与 homeVideoContent.list
        # 拼接显示在"精选"页, 两边都返回会导致卡片重复
        return {"list": []}

    def categoryContent(self, tid, pg, filter, ext):
        self._ensure_scanned()
        if tid == "all":
            items = list(self.sources) + list(self.manual_sources) + list(self.removed)
        elif tid == "ignored":
            items = list(self.ignored)
        else:
            items = ([s for s in self.sources + self.manual_sources if s["type"] == str(tid).upper()]
                     + [s for s in self.removed if not s.get("type") or s["type"] == str(tid).upper()])
        return self._paged(items, pg)

    def _paged(self, items, pg):
        """列表分页: 有数据时 pagecount=9999 允许壳继续翻页拉取剩余内容,
        空页时 pagecount 收敛为当前页码, 阻止空转"""
        try:
            page = int(pg) if pg else 1
        except (TypeError, ValueError):
            page = 1
        if page < 1:
            page = 1
        start = (page - 1) * self.PAGE_SIZE
        videos = [self._source_vod(s) for s in items[start:start + self.PAGE_SIZE]]
        pagecount = 9999 if videos else page
        return {"list": videos, "page": page, "pagecount": pagecount,
                "limit": self.PAGE_SIZE, "total": len(items)}

    def detailContent(self, array):
        source_id = str(array[0]) if isinstance(array, (list, tuple)) and array else str(array or "")
        if source_id in (self.RESCAN_ID, self.STATE_ID):
            # 空返回会让壳弹"获取播放地址失败", 因此点击直接显示扫描状态
            return {"list": [self._status_detail()]}
        if source_id == self.CLEAR_ID:
            with self.lock:
                self._clear_generated()
            return {"list": [self._status_detail()]}
        if source_id == self.STATUS_ID:
            return {"list": [self._status_detail()]}
        if source_id == self.HELP_ID:
            return {"list": [self._help_detail()]}
        source = None
        for s in self.sources + self.ignored + self.manual_sources + self.removed:
            if s["id"] == source_id:
                source = s
                break
        if not source:
            return {"list": [{"vod_id": source_id, "vod_name": "源不存在", "vod_content": "请重新扫描后再试。"}]}
        if source.get("status") == "removed":
            return {"list": [{
                "vod_id": source_id,
                "vod_name": source["name"],
                "vod_pic": "",
                "vod_remarks": "🗑 已删除",
                "vod_content": "该爬虫文件已被删除, 本次扫描已将其站点从列表移除。\n重启 App (或刷新配置) 后站点列表中对应条目将消失。",
            }]}
        status_text = {"manual": "🖐 手工已添加 (指向同一文件, 未重复生成)",
                       "auto": "✅ 已添加 (自动注入)"}.get(source.get("status", "auto"), "")
        site_text = json.dumps(source.get("site") or {}, ensure_ascii=False, indent=2)
        content = (
            "状态: {}\n类型: {}\n文件: {}\n相对路径: {}\n\n生成的站点配置:\n{}\n\n"
            "重启 App (或刷新配置) 后, 该站点会出现在站点列表。"
        ).format(status_text, source["type"], source["path"], source["relative"], site_text)
        return {"list": [{
            "vod_id": source_id,
            "vod_name": source["name"],
            "vod_pic": "",
            "vod_remarks": source.get("type", ""),
            "vod_content": content,
        }]}

    def searchContent(self, key, quick, pg="1"):
        self._ensure_scanned()
        lower = str(key or "").strip().lower()
        items = [s for s in self.sources if lower and lower in s["name"].lower()] if lower else []
        return self._paged(items, pg)

    def playerContent(self, flag, id, vipFlags):
        return {"parse": 0, "url": "", "header": {}, "msg": "这是配置管理条目, 不能作为媒体播放。"}

    def isVideoParse(self, url):
        return False

    def destroy(self):
        return "destroy"

    # ==================== 首页条目 ====================

    def _home_items(self):
        ready = self.write_state.startswith("已写入")
        status_name = "✅ 站点已合并" if ready else "⚠️ 站点未合并"
        if self.error:
            status_name = "❌ " + self.error[:30]
        valid = self.sources + self.manual_sources
        py_seen = len([s for s in valid if s.get("type") == "PY"]) \
            + len([i for i in self.ignored if i.get("type") == "PY"])
        js_seen = len([s for s in valid if s.get("type") == "JS"]) \
            + len([i for i in self.ignored if i.get("type") == "JS"])
        py_ok = len([s for s in self.sources if s.get("type") == "PY"])
        js_ok = len([s for s in self.sources if s.get("type") == "JS"])
        if not self.sources and self.scan_time:
            status_remarks = "未发现爬虫 · 请按「使用说明」放入文件"
        else:
            status_remarks = "{} 个源 · {}".format(len(self.sources), self.write_state)
        return [
            {
                "vod_id": self.HELP_ID,
                "vod_name": "📖 使用说明 (爬虫文件放哪里?)",
                "vod_pic": self._pic_url("folder"),
                "vod_remarks": "首次使用请先点这里",
            },
            {
                "vod_id": self.RESCAN_ID,
                "vod_name": "⚡ 一键扫描并加载",
                "vod_pic": self._pic_url("scan"),
                "vod_remarks": "每次进站自动扫描 · 点此看状态",
            },
            {
                "vod_id": self.STATE_ID,
                "vod_name": "📊 扫描状态",
                "vod_pic": self._pic_url("status"),
                "vod_remarks": "已扫描py/js文件{}/{}个, 已导入{}/{}个".format(
                    py_seen, js_seen, py_ok, js_ok),
            },
            {
                "vod_id": self.STATUS_ID,
                "vod_name": status_name,
                "vod_pic": self._pic_url("status"),
                "vod_remarks": status_remarks,
            },
            {
                "vod_id": self.CLEAR_ID,
                "vod_name": "🗑 一键清除自动站点",
                "vod_pic": self._pic_url("clear"),
                "vod_remarks": "仅移除本脚本生成的站点, 保留手工项",
            },
        ]

